        ]
        events = correlate_linked_violations(
            results, BASE_LINEAGE, links
        )["events"]
        self.assertEqual(len(events), 1)
        self.assertEqual(
            events[0]["sample_refs"],
            [sample_ref("dwd", "b"), sample_ref("ods", "a")],
